import { Audio, interpolate, Sequence, staticFile, useVideoConfig } from "remotion";

// Names of the files generated by scripts/audio.mjs (npm run audio). Keep in
// sync with that script; the catalogue is in the skill's references/audio.md.
export const MUSIC_BPM = {
  raiz: 84,
  ceu: 60,
  travessia: 100,
  semente: 96,
  circuito: 112,
  colheita: 90,
  mutirao: 104,
} as const;
export type MusicName = keyof typeof MUSIC_BPM;

// `travessia` plays once: ancestral for 4 bars, the tech layer enters here.
export const TRAVESSIA_TURN = 288;

export type SfxName =
  | "mata" | "noite" | "rio" | "fogueira" | "chuva" | "vento" | "tech-hum"
  | "bambu" | "chocalho" | "tambor" | "flauta" | "pau-de-chuva" | "madeira" | "pedra" | "palha" | "semente" | "brasa" | "passo-terra"
  | "scan" | "holo" | "dados" | "ia" | "drone" | "satelite" | "power-up" | "click" | "tick" | "notify" | "success" | "glitch" | "typing"
  | "portal" | "whoosh" | "whoosh-short" | "whoosh-reverse" | "riser" | "boom" | "impact-soft" | "tape-stop" | "sparkle" | "pop" | "ding" | "page";

const LOOPING: SfxName[] = ["mata", "noite", "rio", "fogueira", "chuva", "vento", "tech-hum"];
const ONCE: MusicName[] = ["travessia"];

// Frames per beat, to cut actions on the music grid.
export const beatFrames = (music: MusicName, fps = 30) => (60 * fps) / MUSIC_BPM[music];

// Background music for the whole composition, with fades at both ends.
// `stopAt` cuts the music dead on that frame (2-frame fade), the silence right
// before a punchline; pair it with an Sfx on the same frame.
export const Music = ({ name, volume = 0.35, fadeIn = 12, fadeOut = 20, stopAt }: { name: MusicName; volume?: number; fadeIn?: number; fadeOut?: number; stopAt?: number }) => {
  const { durationInFrames } = useVideoConfig();
  const end = stopAt ?? durationInFrames;
  const out = stopAt === undefined ? fadeOut : 2;
  return (
    <Audio
      src={staticFile(`audio/music/${name}.wav`)}
      loop={!ONCE.includes(name)}
      volume={(f) => interpolate(f, [0, fadeIn, end - out, end], [0, volume, volume, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })}
    />
  );
};

// A sound effect starting at frame `at`. Ambiences loop for `length` frames
// with a short fade at both ends.
export const Sfx = ({ name, at = 0, volume = 0.8, length = 90 }: { name: SfxName; at?: number; volume?: number; length?: number }) => {
  const loop = LOOPING.includes(name);
  return (
    <Sequence from={at} durationInFrames={length} layout="none">
      <Audio
        src={staticFile(`audio/sfx/${name}.wav`)}
        loop={loop}
        volume={loop ? (f) => interpolate(f, [0, 10, length - 10, length], [0, volume, volume, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) : volume}
      />
    </Sequence>
  );
};
